import crypto from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const registryPath = path.join(root, 'spec/icons/registry.yaml')
const tokensPath = path.join(root, 'spec/tokens/tokens.json')
const generatedHeader =
  'Generated by scripts/icon-pipeline.mjs. Do not edit manually.'

const outputPaths = {
  webMetadata: 'packages/icons-vue/generated/icon-metadata.json',
  avaloniaXaml: 'dotnet/FsusUI.Avalonia.Icons/Generated/FsusIcons.axaml',
  csharp: 'dotnet/FsusUI.Avalonia.Icons/Generated/FsusIconKeys.g.cs',
  hash: 'generated/icons.hash.json',
}

const sha256 = (content) =>
  crypto.createHash('sha256').update(content).digest('hex')

const pascal = (id) =>
  id
    .split('-')
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join('')

const parseScalar = (value) => {
  const trimmed = value.trim()
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1)
  }
  if (trimmed === 'true') return true
  if (trimmed === 'false') return false
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    return trimmed
      .slice(1, -1)
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)
  }
  return trimmed
}

const readTokenNames = () => {
  const spec = JSON.parse(fs.readFileSync(tokensPath, 'utf8'))
  return new Set((spec.tokens ?? []).map((token) => token.name))
}

const readRegistry = () => {
  const content = fs.readFileSync(registryPath, 'utf8')
  const icons = []
  let current

  for (const line of content.split('\n')) {
    const idMatch = line.match(/^[ ]{2}- id: (.+)$/)
    if (idMatch) {
      current = { id: parseScalar(idMatch[1]) }
      icons.push(current)
      continue
    }

    const fieldMatch = line.match(/^[ ]{4}([A-Za-z0-9]+): (.+)$/)
    if (fieldMatch && current) {
      current[fieldMatch[1]] = parseScalar(fieldMatch[2])
    }
  }

  validateIcons(icons)
  return { content, icons }
}

const validateIcons = (icons) => {
  if (icons.length === 0) throw new Error('Icon registry must not be empty')

  const ids = new Set()
  const tokenNames = readTokenNames()
  for (const icon of icons) {
    for (const field of [
      'id',
      'displayName',
      'category',
      'path',
      'defaultSize',
      'stroke',
      'fill',
      'mode',
      'decorativeByDefault',
    ]) {
      if (icon[field] === undefined || icon[field] === '') {
        throw new Error(`${icon.id ?? 'icon'} is missing ${field}`)
      }
    }
    if (ids.has(icon.id)) throw new Error(`Duplicate icon id ${icon.id}`)
    ids.add(icon.id)
    if (!tokenNames.has(icon.defaultSize)) {
      throw new Error(`${icon.id} must use shared icon size tokens`)
    }
    if (!tokenNames.has(icon.stroke)) {
      throw new Error(`${icon.id} must use shared icon stroke tokens`)
    }
    if (!tokenNames.has(icon.fill)) {
      throw new Error(`${icon.id} must use shared icon fill tokens`)
    }
    if (!fs.existsSync(path.join(root, icon.source))) {
      throw new Error(`${icon.id} source ${icon.source} does not exist`)
    }
  }
}

const xmlEscape = (value) =>
  String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')

const renderWebMetadata = (icons) => {
  const json = JSON.stringify(
    {
      generatedBy: 'scripts/icon-pipeline.mjs',
      note: generatedHeader,
      icons,
    },
    null,
    2,
  )

  return `${json.replace(
    /\n( {6}"aliases": )\[\n {8}("[^"\n]+")\n {6}\]/g,
    '\n$1[$2]',
  )}\n`
}

const renderAvaloniaXaml = (icons) => {
  const lines = [
    '<ResourceDictionary',
    '  xmlns="https://github.com/avaloniaui"',
    '  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">',
    `  <!-- ${generatedHeader} -->`,
  ]

  for (const icon of icons) {
    lines.push(
      `  <StreamGeometry x:Key="FsusIcon${pascal(icon.id)}">${xmlEscape(
        icon.path,
      )}</StreamGeometry>`,
    )
  }

  lines.push('</ResourceDictionary>', '')
  return lines.join('\n')
}

const renderCsharp = (icons) => {
  const lines = [
    '// <auto-generated />',
    `// ${generatedHeader}`,
    'namespace FsusUI.Avalonia.Icons;',
    '',
    'public static class FsusIconKeys',
    '{',
  ]

  for (const icon of icons) {
    lines.push(
      `  public const string ${pascal(icon.id)} = "FsusIcon${pascal(icon.id)}";`,
    )
  }

  lines.push('}', '')
  return lines.join('\n')
}

const renderAll = () => {
  const { content, icons } = readRegistry()
  const files = {
    [outputPaths.webMetadata]: renderWebMetadata(icons),
    [outputPaths.avaloniaXaml]: renderAvaloniaXaml(icons),
    [outputPaths.csharp]: renderCsharp(icons),
  }

  files[outputPaths.hash] = `${JSON.stringify(
    {
      generatedBy: 'scripts/icon-pipeline.mjs',
      note: generatedHeader,
      source: 'spec/icons/registry.yaml',
      sourceHash: sha256(content),
      outputs: Object.fromEntries(
        Object.entries(files).map(([filePath, fileContent]) => [
          filePath,
          sha256(fileContent),
        ]),
      ),
    },
    null,
    2,
  )}\n`

  return files
}

const writeFiles = (files) => {
  for (const [relativePath, content] of Object.entries(files)) {
    const absolutePath = path.join(root, relativePath)
    fs.mkdirSync(path.dirname(absolutePath), { recursive: true })
    fs.writeFileSync(absolutePath, content)
    console.log(`wrote ${relativePath}`)
  }
}

const checkFiles = (files) => {
  const failures = []
  for (const [relativePath, expected] of Object.entries(files)) {
    const absolutePath = path.join(root, relativePath)
    if (!fs.existsSync(absolutePath)) {
      failures.push(`${relativePath} is missing`)
      continue
    }
    if (fs.readFileSync(absolutePath, 'utf8') !== expected) {
      failures.push(`${relativePath} is stale`)
    }
  }
  if (failures.length > 0) {
    throw new Error(`Icon artifacts are not current:\n${failures.join('\n')}`)
  }
  console.log('Icon artifacts are current.')
}

const lint = () => {
  const { icons } = readRegistry()
  const aliases = new Set()
  for (const icon of icons) {
    for (const alias of icon.aliases ?? []) {
      if (aliases.has(alias)) throw new Error(`Duplicate icon alias ${alias}`)
      aliases.add(alias)
    }
  }
  console.log('Icon registry is valid.')
}

const command = process.argv[2]

try {
  if (command === 'generate') writeFiles(renderAll())
  else if (command === 'check') checkFiles(renderAll())
  else if (command === 'lint') lint()
  else
    throw new Error(
      'Usage: node scripts/icon-pipeline.mjs <generate|check|lint>',
    )
} catch (error) {
  console.error(error instanceof Error ? error.message : error)
  process.exitCode = 1
}
